<script setup>
import draggable from'vuedraggable';const props=defineProps({modelValue:{type:Array,default:()=>[]},disabled:Boolean});const emit=defineEmits(['update:modelValue']);function add(){emit('update:modelValue',[...props.modelValue,{client_key:`folder_${Date.now()}`,parent_client_key:null,name:'New folder',client_visible:true}])}function remove(i){const key=props.modelValue[i].client_key;emit('update:modelValue',props.modelValue.filter((f,index)=>index!==i&&f.parent_client_key!==key))}
</script>
<template><div><draggable :model-value="modelValue" item-key="client_key" handle=".drag-handle" :disabled="disabled" @update:model-value="emit('update:modelValue',$event)"><template #item="{element,index}"><div class="mb-2 grid gap-3 border border-dark bg-light p-3 sm:grid-cols-[32px_1fr_1fr_auto]"><button type="button" class="drag-handle">☰</button><div class="admin-field"><label>Name</label><input v-model="element.name" :disabled="disabled"></div><div class="admin-field"><label>Parent</label><select v-model="element.parent_client_key" :disabled="disabled"><option :value="null">Root</option><option v-for="folder in modelValue.filter(f=>f.client_key!==element.client_key)" :key="folder.client_key" :value="folder.client_key">{{folder.name}}</option></select></div><div class="flex items-center gap-3"><label><input v-model="element.client_visible" type="checkbox" :disabled="disabled"> Client</label><button v-if="!disabled" type="button" @click="remove(index)">×</button></div></div></template></draggable><button v-if="!disabled" type="button" class="admin-button" @click="add">Add folder</button></div></template>